# Run from the package root after 54b, 56 and 58:  Rscript data-raw/qa/62_st_louis_section.R
# Writes the section "A known case: the St. Louis tornado of 16 May 2025" of data-raw/known_issues.md (between <!-- st-louis:start --> and <!-- st-louis:end -->). All numbers are read from the data and the saved results of the QA scripts.
suppressMessages({library(sf); library(dplyr)}); source("data-raw/qa/helpers.R"); for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f)
f0 <- function(x) formatC(x, format = "d", big.mark = ","); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x); id <- "2025_2505161339-01"
tt <- st_drop_geometry(tornado_tracks); t1 <- tt[tt$tornado_id == id, ]; sm <- survey_matches[survey_matches$tornado_id == id, ]; ex <- tornado_exposure[tornado_exposure$tornado_id == id, ]; se <- survey_exposure[survey_exposure$tornado_id == id, ]
raw <- read.csv(qa_spc_csv(), stringsAsFactors = FALSE); rr <- raw[raw$date == "2025-05-16" & raw$slat > 38.6 & raw$slat < 38.8 & raw$slon > -90.4 & raw$slon < -89.9, ]
L <- readRDS(qa_out("dat_full_layer1.rds")); L$sd <- as.POSIXct(as.numeric(L$stormdate) / 1000, origin = "1970-01-01", tz = "UTC"); dl <- L[L$wfo == "LSX" & as.Date(L$sd) == as.Date("2025-05-16") & L$objectid %in% c(2671572, 2671973), ]; dl <- st_drop_geometry(dl)[order(dl$objectid), ]
nc <- readRDS(qa_out("ncei_comparison.rds")); ev <- nc$R$st_louis_events; ps <- readRDS(qa_out("pairing_study.rds"))$R; ch <- ps$c_all; ca <- ps$a; names(ca) <- make.names(names(ca))
l1 <- dl[dl$objectid == 2671572, ]; mo <- sum(substr(ex$ZCTA, 1, 2) == "63"); il <- sum(substr(ex$ZCTA, 1, 2) == "62"); sd <- se$ZCTA
txt <- c("<!-- st-louis:start -->", "## A known case: the St. Louis tornado of 16 May 2025", "",
 paste0("SPC's 2025 file (released 24 April 2026) has one whole-track record for the tornado, `", id, "`: ", sprintf("%.2f", t1$len_mi), " miles, a width of ", f0(t1$wid_yd), " yards, rating ", t1$magnitude, ", ", t1$total_injury, " injuries and ", t1$total_fatality, " deaths, from ", sprintf("%.4f", rr$slat[1]), ", ", sprintf("%.4f", rr$slon[1]), " to ", sprintf("%.4f", rr$elat[1]), ", ", sprintf("%.4f", rr$elon[1]),
   " (Missouri into Illinois). The file also has two segment rows of it (`", rr$om[2], "`: ", sprintf("%.2f", rr$len[2]), " miles, rating ", rr$mag[2], "; `", rr$om[3], "`: ", sprintf("%.2f", rr$len[3]), " miles in Illinois, rating ", rr$mag[3], "), which the published data do not include. The NCEI Storm Events file has three events for it, rated EF", ev$TOR_F_SCALE[ev$STATE == "MISSOURI"][1] %>% sub("EF", "", .), " (", ev$TOR_LENGTH[ev$STATE == "MISSOURI"][1], " miles), EF", ev$TOR_F_SCALE[ev$STATE == "MISSOURI"][2] %>% sub("EF", "", .), " (", ev$TOR_LENGTH[ev$STATE == "MISSOURI"][2], " miles, with ", ev$INJURIES_DIRECT[ev$STATE == "MISSOURI"][2], " injuries and ", ev$DEATHS_DIRECT[ev$STATE == "MISSOURI"][2], " deaths) and ", ev$TOR_F_SCALE[ev$STATE == "ILLINOIS"][1], " (", ev$TOR_LENGTH[ev$STATE == "ILLINOIS"][1], " miles)."), "",
 paste0("The NWS survey data (the Damage Assessment Toolkit) have two lines for it: survey line ", dl$objectid[2], " (", dl$efscale[2], ", ", sprintf("%.2f", dl$length[2]), " miles, width ", f0(dl$width[2]), " yards, from ", sprintf("%.4f", dl$startlat[2]), ", ", sprintf("%.4f", dl$startlon[2]), " to ", sprintf("%.4f", dl$endlat[2]), ", ", sprintf("%.4f", dl$endlon[2]), ") and survey line ", dl$objectid[1], " (", dl$efscale[1], ", ", sprintf("%.2f", dl$length[1]), " miles, width ", f0(dl$width[1]), " yards, from ", sprintf("%.4f", dl$startlat[1]), ", ", sprintf("%.4f", dl$startlon[1]), " to ", sprintf("%.4f", dl$endlat[1]), ", ", sprintf("%.4f", dl$endlon[1]), "). ",
   "The NWS reanalysis of May 2026 ([Updated Damage Assessment for May 16, 2025 St. Louis Tornado](https://www.weather.gov/lsx/STLTornado); reported by [STLPR on 15 May 2026](https://www.stlpr.org/news-briefs/2026-05-15/may-16-tornado-reached-1-8-miles-wide)) describes an EF-3 tornado with a width increased to 3,168 yards and a second tornado rated EF-1 with a path width of 525 yards. SPC's release of 24 April 2026 came before this update, so SPC's rating of ", t1$magnitude, " and its single record predate it. SPC can predate NWS revisions in general, and the package stores each SPC release as it was (stored years are frozen)."), "",
 paste0("**What the survey layer holds.** `survey_matches` pairs the tornado with survey line ", sm$survey_line_id, " (", l1$efscale, "): distance ", sprintf("%.2f", sm$distance_km), " km, length ratio ", sprintf("%.4f", sm$length_ratio), ", different state (`same_state` = ", sm$same_state, "), second-closest distance ", sprintf("%.2f", sm$second_distance_tornado_km), " km, status `", sm$status, "`. The ratio of ", sprintf("%.4f", sm$length_ratio), " is the length of that line (", sprintf("%.2f", l1$length), " miles) over SPC's (", sprintf("%.2f", t1$len_mi), " miles): the line lies in the Illinois part of the SPC path. `survey_exposure` has ", length(sd), " ZCTAs for it (", paste(sort(sd), collapse = ", "), "), none in Missouri, while the SPC rows have ", nrow(ex), " ZCTAs (", mo, " of them in Missouri, ", il, " in Illinois). The EF3 line, which holds the main damage (",
   t1$total_injury, " injuries and ", t1$total_fatality, " deaths), is not in the survey layer, because the pairing allows one survey line per tornado."), "",
 paste0("**Why the pairing chose this line.** The distance of the pairing compares 21 points of the survey line with 21 points of the SPC line by position (first with first, last with last). A survey line that covers only part of the SPC path therefore has a large distance even when it lies on the path: for the two lines the distance is ", sprintf("%.2f", ca$index_aligned_km[2]), " km (EF3 line) and ", sprintf("%.2f", ca$index_aligned_km[1]), " km (EF1 line); the one-sided distance (the mean distance from the survey line's own 21 points to the SPC line) is ", sprintf("%.2f", ca$one_sided_km[2]), " km and ", sprintf("%.2f", ca$one_sided_km[1]), " km. The EF1 line was chosen because its distance was the smaller of the two by ", sprintf("%.2f", ca$index_aligned_km[2] - ca$index_aligned_km[1]), " km."), "",
 paste0("**How often a swath covers only part of the SPC path.** Of the ", f0(ch[["n"]]), " included line tracks (a usable swath and a straight SPC line) on a fresh full-resolution fetch, ", f0(ch[["n_below_0.8"]]), " (", pc(ch[["share_below_0.8"]]), ") have a swath whose extent along the SPC start-to-end line is less than 80% of that line (the extent is measured by projecting the swath's vertices onto the SPC line, from 0 at the start to 1 at the end; 80% is a descriptive value, not a tested choice)."), "",
 "A check of the documented state of this case is in `data-raw/qa/check_data_integrity.R` (labeled as a known limitation, expected to change when the pairing allows several lines per tornado).", "<!-- st-louis:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- st-louis:start -->", kl, fixed = TRUE); b <- grep("<!-- st-louis:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("^## Point tracks|^<!-- no-end-point:start -->", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
